package com.injuryanimations;

import net.runelite.api.gameval.AnimationID;
import org.junit.Test;

import static org.junit.Assert.assertEquals;

public class InjuredAnimationSelectorTest
{
	@Test
	public void usesHumanDazedProfileForCompatibleEquipment()
	{
		assertEquals(AnimationID.HUMAN_DAZED_WALK, InjuredAnimationSelector.selectWalk(false));
		assertEquals(AnimationID.HUMAN_DAZED_RUN, InjuredAnimationSelector.selectRun(false));
		assertEquals(AnimationID.HUMAN_DAZED_READY, InjuredAnimationSelector.selectIdle(false));
	}

	@Test
	public void usesVarrockLimpForShieldSafeWalkAndRun()
	{
		assertEquals(AnimationID.FAI_VARROCK_LIMP_WALK, InjuredAnimationSelector.selectWalk(true));
		assertEquals(AnimationID.FAI_VARROCK_LIMP_WALK, InjuredAnimationSelector.selectRun(true));
	}

	@Test
	public void usesDrunkPlayerIdleForBulkyOffhands()
	{
		assertEquals(AnimationID.DRUNK_PLAYER_READY, InjuredAnimationSelector.selectIdle(true));
	}
}

package com.injuryanimations;

import java.util.Collections;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class OffhandAnimationCompatibilityTest
{
	@Test
	public void recognizesBulkyOffhandNameTermsCaseInsensitively()
	{
		assertTrue(requiresShieldSafeAnimation("Dragon shield"));
		assertTrue(requiresShieldSafeAnimation("ELIDINIS' WARD"));
		assertTrue(requiresShieldSafeAnimation("Abyssal lantern"));
		assertTrue(requiresShieldSafeAnimation("Twisted buckler"));
	}

	@Test
	public void leavesKnownCompactOffhandsOnTheConfiguredAnimation()
	{
		assertFalse(requiresShieldSafeAnimation("Avernic defender"));
		assertFalse(requiresShieldSafeAnimation("Book of darkness"));
	}

	@Test
	public void treatsAnEmptyOffhandAsCompatible()
	{
		assertFalse(OffhandAnimationCompatibility.requiresShieldSafeAnimation(-1, null));
	}

	@Test
	public void supportsObservedItemIdExceptionsWithoutGuessingByName()
	{
		assertTrue(OffhandAnimationCompatibility.requiresShieldSafeAnimation(
			12345,
			"Toktz-ket-xil",
			Collections.singleton(12345)
		));
		assertFalse(OffhandAnimationCompatibility.requiresShieldSafeAnimation(
			12345,
			"Toktz-ket-xil",
			Collections.emptySet()
		));
	}

	private static boolean requiresShieldSafeAnimation(String itemName)
	{
		return OffhandAnimationCompatibility.requiresShieldSafeAnimation(1, itemName);
	}
}

package com.injuryanimations;

