package com.injuryanimations;

import net.runelite.api.gameval.AnimationID;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class InjuryAnimationPolicyTest
{
	@Test
	public void pausesOverridesDuringAnAction()
	{
		assertFalse(InjuryAnimationPolicy.shouldOverride(
			true,
			InjuryState.INJURED,
			true,
			AnimationID.HUMAN_DHSWORD_SLASH
		));
		assertTrue(InjuryAnimationPolicy.shouldOverride(true, InjuryState.INJURED, true, -1));
	}

	@Test
	public void canKeepOverridesDuringAnActionWhenPauseIsDisabled()
	{
		assertTrue(InjuryAnimationPolicy.shouldOverride(
			true,
			InjuryState.INJURED,
			false,
			AnimationID.HUMAN_DHSWORD_SLASH
		));
	}

	@Test
	public void requiresEnabledMovementAndAnInjuryState()
	{
		assertFalse(InjuryAnimationPolicy.shouldOverride(false, InjuryState.INJURED, false, -1));
		assertFalse(InjuryAnimationPolicy.shouldOverride(true, InjuryState.HEALTHY, false, -1));
		assertFalse(InjuryAnimationPolicy.shouldOverride(true, null, false, -1));
		assertTrue(InjuryAnimationPolicy.shouldOverride(true, InjuryState.INJURED, false, -1));
	}
}

