package com.injuryanimations;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class InjuryStateTest
{
	private static InjuryState fromHitpoints(int currentHitpoints, int maximumHitpoints)
	{
		return InjuryState.fromHitpoints(
			currentHitpoints,
			maximumHitpoints,
			InjuryAnimationsConfig.DEFAULT_INJURED_THRESHOLD
		);
	}

	@Test
	public void mapsExactThresholdBoundaries()
	{
		assertEquals(InjuryState.HEALTHY, fromHitpoints(41, 100));
		assertEquals(InjuryState.INJURED, fromHitpoints(40, 100));
		assertEquals(InjuryState.INJURED, fromHitpoints(1, 100));
	}

	@Test
	public void comparesPercentagesWithoutRoundingDown()
	{
		assertEquals(InjuryState.HEALTHY, fromHitpoints(40, 99));
		assertEquals(InjuryState.INJURED, fromHitpoints(39, 99));
	}

	@Test
	public void mapsCustomThresholdBoundaries()
	{
		assertEquals(InjuryState.HEALTHY, InjuryState.fromHitpoints(61, 100, 60));
		assertEquals(InjuryState.INJURED, InjuryState.fromHitpoints(60, 100, 60));
	}

	@Test
	public void ignoresInvalidMaximumHitpoints()
	{
		assertNull(fromHitpoints(50, 0));
		assertNull(fromHitpoints(50, -1));
	}

	@Test
	public void ignoresInvalidCurrentHitpoints()
	{
		assertNull(fromHitpoints(0, 99));
		assertNull(fromHitpoints(-1, 99));
	}

	@Test
	public void ignoresInvalidThresholds()
	{
		assertNull(InjuryState.fromHitpoints(50, 100, 0));
		assertNull(InjuryState.fromHitpoints(50, 100, 100));
	}

	@Test
	public void acceptsBoostedHitpointsAboveTheRealLevel()
	{
		assertEquals(InjuryState.HEALTHY, fromHitpoints(110, 99));
	}
}

package com.injuryanimations;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class AnimationOverrideControllerTest
{
	private static final int REPLACEMENT_ANIMATION = 999;
	private static final int SECOND_REPLACEMENT_ANIMATION = 998;

	private static final AnimationOverrideController.Access<TestActor> ACCESS =
		new AnimationOverrideController.Access<TestActor>()
		{
			@Override
			public int getAnimation(TestActor actor)
			{
				return actor.walkAnimation;
			}

			@Override
			public void setAnimation(TestActor actor, int animationId)
			{
				actor.walkAnimation = animationId;
				actor.writeCount++;
			}
		};

	private final AnimationOverrideController<TestActor> controller =
		new AnimationOverrideController<>(ACCESS);

	@Test
	public void appliesAndRestoresOriginalAnimation()
	{
		TestActor actor = new TestActor(100);

		controller.apply(actor, REPLACEMENT_ANIMATION);
		assertEquals(REPLACEMENT_ANIMATION, actor.walkAnimation);
		assertTrue(controller.isTracking(actor));

		controller.restore();
		assertEquals(100, actor.walkAnimation);
		assertFalse(controller.isActive());
	}

	@Test
	public void doesNotOverwriteANewerAnimationWhenRestoring()
	{
		TestActor actor = new TestActor(100);
		controller.apply(actor, REPLACEMENT_ANIMATION);
		actor.walkAnimation = 200;

		controller.restore();

		assertEquals(200, actor.walkAnimation);
		assertFalse(controller.isActive());
	}

	@Test
	public void recapturesAnimationAfterAppearanceChange()
	{
		TestActor actor = new TestActor(100);
		controller.apply(actor, REPLACEMENT_ANIMATION);
		actor.walkAnimation = 200;

		controller.apply(actor, REPLACEMENT_ANIMATION);
		controller.restore();

		assertEquals(200, actor.walkAnimation);
	}

	@Test
	public void restoresPreviousActorBeforeSwitchingActors()
	{
		TestActor firstActor = new TestActor(100);
		TestActor secondActor = new TestActor(200);

		controller.apply(firstActor, REPLACEMENT_ANIMATION);
		controller.apply(secondActor, REPLACEMENT_ANIMATION);

		assertEquals(100, firstActor.walkAnimation);
		assertEquals(REPLACEMENT_ANIMATION, secondActor.walkAnimation);
		assertTrue(controller.isTracking(secondActor));
	}

	@Test
	public void repeatedApplicationPreservesOriginalAnimation()
	{
		TestActor actor = new TestActor(100);

		controller.apply(actor, REPLACEMENT_ANIMATION);
		controller.apply(actor, REPLACEMENT_ANIMATION);
		controller.restore();

		assertEquals(100, actor.walkAnimation);
		assertEquals(2, actor.writeCount);
	}

	@Test
	public void doesNotClaimAnAnimationAlreadyUsingTheReplacement()
	{
		TestActor actor = new TestActor(REPLACEMENT_ANIMATION);

		controller.apply(actor, REPLACEMENT_ANIMATION);
		controller.restore();

		assertEquals(REPLACEMENT_ANIMATION, actor.walkAnimation);
		assertEquals(0, actor.writeCount);
		assertFalse(controller.isActive());
	}

	@Test
	public void switchesReplacementWithoutLosingOriginalAnimation()
	{
		TestActor actor = new TestActor(100);

		controller.apply(actor, REPLACEMENT_ANIMATION);
		controller.apply(actor, SECOND_REPLACEMENT_ANIMATION);

		assertEquals(SECOND_REPLACEMENT_ANIMATION, actor.walkAnimation);

		controller.restore();
		assertEquals(100, actor.walkAnimation);
	}

	@Test
	public void switchesForEquipmentChangesAndBackWithoutLosingOriginalAnimation()
	{
		TestActor actor = new TestActor(100);

		controller.apply(actor, REPLACEMENT_ANIMATION);
		controller.apply(actor, SECOND_REPLACEMENT_ANIMATION);
		controller.apply(actor, REPLACEMENT_ANIMATION);

		assertEquals(REPLACEMENT_ANIMATION, actor.walkAnimation);

		controller.restore();
		assertEquals(100, actor.walkAnimation);
	}

	@Test
	public void doesNotRestoreOverANewerAnimationAfterReplacementSwitch()
	{
		TestActor actor = new TestActor(100);

		controller.apply(actor, REPLACEMENT_ANIMATION);
		controller.apply(actor, SECOND_REPLACEMENT_ANIMATION);
		actor.walkAnimation = 200;
		controller.restore();

		assertEquals(200, actor.walkAnimation);
	}

	private static final class TestActor
	{
		private int walkAnimation;
		private int writeCount;

		private TestActor(int walkAnimation)
		{
			this.walkAnimation = walkAnimation;
		}
	}
}

package com.injuryanimations;

import com.google.inject.Provides;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.events.AnimationChanged;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.PlayerChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

import static net.runelite.api.gameval.InventoryID.WORN;

@Slf4j
@PluginDescriptor(
	name = "Injury Animations",
	description = "Makes your character limp when injured, with shield-safe animations for bulky off-hands."
)
public class InjuryAnimationsPlugin extends Plugin
{
	private static final AnimationOverrideController.Access<Player> PLAYER_WALK_ANIMATION_ACCESS =
		new AnimationOverrideController.Access<Player>()
		{
			@Override
			public int getAnimation(Player player)
			{
				return player.getWalkAnimation();
			}

			@Override
			public void setAnimation(Player player, int animationId)
			{
				player.setWalkAnimation(animationId);
			}
		};
	private static final AnimationOverrideController.Access<Player> PLAYER_RUN_ANIMATION_ACCESS =
		new AnimationOverrideController.Access<Player>()
		{
			@Override
			public int getAnimation(Player player)
			{
				return player.getRunAnimation();
			}

			@Override
			public void setAnimation(Player player, int animationId)
			{
				player.setRunAnimation(animationId);
			}
		};
	private static final AnimationOverrideController.Access<Player> PLAYER_IDLE_ANIMATION_ACCESS =
		new AnimationOverrideController.Access<Player>()
		{
			@Override
			public int getAnimation(Player player)
			{
				return player.getIdlePoseAnimation();
			}

			@Override
			public void setAnimation(Player player, int animationId)
			{
				player.setIdlePoseAnimation(animationId);
			}
		};

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private InjuryAnimationsConfig config;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private InjuryAnimationsOverlay overlay;

	private final AnimationOverrideController<Player> walkAnimationController =
		new AnimationOverrideController<>(PLAYER_WALK_ANIMATION_ACCESS);
	private final AnimationOverrideController<Player> runAnimationController =
		new AnimationOverrideController<>(PLAYER_RUN_ANIMATION_ACCESS);
	private final AnimationOverrideController<Player> idleAnimationController =
		new AnimationOverrideController<>(PLAYER_IDLE_ANIMATION_ACCESS);

	private volatile boolean running;
	private volatile long lifecycleGeneration;
	private Player localPlayer;
	private InjuryState injuryState;

	@Override
	protected void startUp()
	{
		running = true;
		lifecycleGeneration++;
		overlayManager.add(overlay);
		refreshOnClientThread();
	}

	@Override
	protected void shutDown()
	{
		running = false;
		lifecycleGeneration++;
		overlayManager.remove(overlay);
		clientThread.invoke(this::clearClientState);
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged configChanged)
	{
		if (!InjuryAnimationsConfig.GROUP.equals(configChanged.getGroup()))
		{
			return;
		}

		boolean refreshMovement = InjuryAnimationsConfig.KEY_ENABLE_INJURED_MOVEMENT.equals(configChanged.getKey())
			|| InjuryAnimationsConfig.KEY_INJURED_THRESHOLD.equals(configChanged.getKey())
			|| InjuryAnimationsConfig.KEY_PAUSE_DURING_ACTIONS.equals(configChanged.getKey());

		if (refreshMovement)
		{
			refreshOnClientThread();
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged gameStateChanged)
	{
		if (gameStateChanged.getGameState() != GameState.LOGGED_IN)
		{
			clearClientState();
		}
	}

	@Subscribe
	public void onGameTick(GameTick gameTick)
	{
		updateInjuryStateAndAnimations();
	}

	@Subscribe
	public void onAnimationChanged(AnimationChanged animationChanged)
	{
		if (running && animationChanged.getActor() == client.getLocalPlayer())
		{
			updateInjuryStateAndAnimations();
		}
	}

	@Subscribe
	public void onPlayerChanged(PlayerChanged playerChanged)
	{
		Player changedPlayer = playerChanged.getPlayer();
		if (!running)
		{
			return;
		}

		Player currentLocalPlayer = updateLocalPlayerReference();
		if (currentLocalPlayer == null || changedPlayer != currentLocalPlayer)
		{
			return;
		}

		updateAnimationOverrides(currentLocalPlayer);
	}

	private void updateInjuryStateAndAnimations()
	{
		if (!running)
		{
			return;
		}

		if (client.getGameState() != GameState.LOGGED_IN)
		{
			clearClientState();
			return;
		}

		Player currentLocalPlayer = updateLocalPlayerReference();
		if (currentLocalPlayer == null)
		{
			return;
		}

		if (!config.enableInjuredMovement())
		{
			restoreAnimationOverrides();
		}

		int currentHitpoints = client.getBoostedSkillLevel(Skill.HITPOINTS);
		int maximumHitpoints = client.getRealSkillLevel(Skill.HITPOINTS);
		InjuryState nextInjuryState = InjuryState.fromHitpoints(
			currentHitpoints,
			maximumHitpoints,
			config.injuredThreshold()
		);
		if (nextInjuryState == null)
		{
			return;
		}

		if (injuryState != null && nextInjuryState != injuryState)
		{
			log.debug(
				"Injury state changed from {} to {} ({} / {} HP)",
				injuryState,
				nextInjuryState,
				currentHitpoints,
				maximumHitpoints
			);
		}
		injuryState = nextInjuryState;

		updateAnimationOverrides(currentLocalPlayer);
	}

	private void updateAnimationOverrides(Player currentLocalPlayer)
	{
		if (!shouldUseInjuredAnimations(currentLocalPlayer))
		{
			restoreAnimationOverrides();
			return;
		}

		boolean shieldSafe = requiresShieldSafeAnimation();

		walkAnimationController.apply(
			currentLocalPlayer,
			InjuredAnimationSelector.selectWalk(shieldSafe)
		);

		runAnimationController.apply(
			currentLocalPlayer,
			InjuredAnimationSelector.selectRun(shieldSafe)
		);
		idleAnimationController.apply(
			currentLocalPlayer,
			InjuredAnimationSelector.selectIdle(shieldSafe)
		);
	}

	private Player updateLocalPlayerReference()
	{
		Player currentLocalPlayer = client.getLocalPlayer();
		if (currentLocalPlayer != localPlayer)
		{
			restoreAnimationOverrides();
			localPlayer = currentLocalPlayer;
			injuryState = null;
		}

		return currentLocalPlayer;
	}

	private void clearClientState()
	{
		restoreAnimationOverrides();
		localPlayer = null;
		injuryState = null;
	}

	private boolean shouldUseInjuredAnimations(Player currentLocalPlayer)
	{
		return InjuryAnimationPolicy.shouldOverride(
			config.enableInjuredMovement(),
			injuryState,
			config.pauseDuringActions(),
			currentLocalPlayer.getAnimation()
		);
	}

	private void restoreAnimationOverrides()
	{
		walkAnimationController.restore();
		runAnimationController.restore();
		idleAnimationController.restore();
	}

	private boolean requiresShieldSafeAnimation()
	{
		ItemContainer equipment = client.getItemContainer(WORN);
		if (equipment == null)
		{
			return false;
		}

		Item offhand = equipment.getItem(EquipmentInventorySlot.SHIELD.getSlotIdx());
		if (offhand == null || offhand.getId() < 0)
		{
			return false;
		}

		ItemComposition itemComposition = client.getItemDefinition(offhand.getId());
		return OffhandAnimationCompatibility.requiresShieldSafeAnimation(
			offhand.getId(),
			itemComposition.getName()
		);
	}

	InjuryState getInjuryState()
	{
		return injuryState;
	}

	private void refreshOnClientThread()
	{
		long scheduledGeneration = lifecycleGeneration;
		clientThread.invoke(() ->
		{
			if (running && lifecycleGeneration == scheduledGeneration)
			{
				updateInjuryStateAndAnimations();
			}
		});
	}

	@Provides
	InjuryAnimationsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(InjuryAnimationsConfig.class);
	}
}

package com.injuryanimations;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup(InjuryAnimationsConfig.GROUP)
public interface InjuryAnimationsConfig extends Config
{
	String GROUP = "injury-animations";
	String KEY_ENABLE_INJURED_MOVEMENT = "enableInjuredMovement";
	String KEY_INJURED_THRESHOLD = "injuredThreshold";
	String KEY_PAUSE_DURING_ACTIONS = "pauseDuringActions";
	String KEY_ENABLE_INJURY_OUTLINE = "enableInjuryOutline";

	int MIN_INJURED_THRESHOLD = 1;
	int MAX_INJURED_THRESHOLD = 99;
	int DEFAULT_INJURED_THRESHOLD = 40;

	@ConfigItem(
		keyName = KEY_ENABLE_INJURED_MOVEMENT,
		name = "Enable injured movement",
		description = "Replace the local player's walk, run, and idle animations while injured.",
		position = 1
	)
	default boolean enableInjuredMovement()
	{
		return true;
	}

	@ConfigItem(
		keyName = KEY_INJURED_THRESHOLD,
		name = "Injured threshold",
		description = "HP percentage at or below which the player becomes injured.",
		position = 2
	)
	@Range(min = MIN_INJURED_THRESHOLD, max = MAX_INJURED_THRESHOLD)
	@Units(Units.PERCENT)
	default int injuredThreshold()
	{
		return DEFAULT_INJURED_THRESHOLD;
	}

	@ConfigItem(
		keyName = KEY_PAUSE_DURING_ACTIONS,
		name = "Pause during actions",
		description = "Temporarily restore normal movement poses during attacks, skilling, emotes, and other actions.",
		position = 3
	)
	default boolean pauseDuringActions()
	{
		return true;
	}

	@ConfigItem(
		keyName = KEY_ENABLE_INJURY_OUTLINE,
		name = "Enable injury outline",
		description = "Pulse a local cosmetic outline while injured.",
		position = 4
	)
	default boolean enableInjuryOutline()
	{
		return true;
	}
}

package com.injuryanimations;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;

final class InjuryAnimationsOverlay extends Overlay
{
	private static final int OUTLINE_WIDTH = 2;
	private static final int OUTLINE_FEATHER = 2;

	private final Client client;
	private final InjuryAnimationsPlugin plugin;
	private final InjuryAnimationsConfig config;
	private final ModelOutlineRenderer modelOutlineRenderer;

	@Inject
	private InjuryAnimationsOverlay(
		Client client,
		InjuryAnimationsPlugin plugin,
		InjuryAnimationsConfig config,
		ModelOutlineRenderer modelOutlineRenderer)
	{
		super(plugin);
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		this.modelOutlineRenderer = modelOutlineRenderer;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		InjuryState state = plugin.getInjuryState();
		if (!config.enableInjuryOutline()
			|| client.getGameState() != GameState.LOGGED_IN
			|| state == null
			|| state == InjuryState.HEALTHY)
		{
			return null;
		}

		Player localPlayer = client.getLocalPlayer();
		if (localPlayer != null)
		{
			modelOutlineRenderer.drawOutline(
				localPlayer,
				OUTLINE_WIDTH,
				outlineColor(client.getGameCycle()),
				OUTLINE_FEATHER
			);
		}

		return null;
	}

	static Color outlineColor(int gameCycle)
	{
		double pulse = (Math.sin(gameCycle / 12.0) + 1.0) / 2.0;
		return new Color(190 + (int) (65 * pulse), 15, 20, 210);
	}
}

