package com.injuryanimations;

enum InjuryState
{
	HEALTHY,
	INJURED;

	static InjuryState fromHitpoints(
		int currentHitpoints,
		int maximumHitpoints,
		int injuredThreshold)
	{
		if (currentHitpoints <= 0
			|| maximumHitpoints <= 0
			|| injuredThreshold < InjuryAnimationsConfig.MIN_INJURED_THRESHOLD
			|| injuredThreshold > InjuryAnimationsConfig.MAX_INJURED_THRESHOLD)
		{
			return null;
		}

		long scaledCurrentHitpoints = (long) currentHitpoints * 100;
		return scaledCurrentHitpoints > (long) maximumHitpoints * injuredThreshold
			? HEALTHY
			: INJURED;
	}
}

package com.injuryanimations;

final class AnimationOverrideController<T>
{
	interface Access<T>
	{
		int getAnimation(T actor);

		void setAnimation(T actor, int animationId);
	}

	private final Access<T> access;

	private T actor;
	private int originalAnimation;
	private int replacementAnimation;

	AnimationOverrideController(Access<T> access)
	{
		this.access = access;
	}

	boolean isActive()
	{
		return actor != null;
	}

	boolean isTracking(T candidate)
	{
		return actor != null && actor == candidate;
	}

	void apply(T candidate, int desiredAnimation)
	{
		if (candidate == null)
		{
			restore();
			return;
		}

		if (actor != null && actor != candidate)
		{
			restore();
		}

		int currentAnimation = access.getAnimation(candidate);
		if (actor == candidate && currentAnimation == replacementAnimation)
		{
			if (replacementAnimation != desiredAnimation)
			{
				replacementAnimation = desiredAnimation;
				access.setAnimation(candidate, desiredAnimation);
			}
			return;
		}

		if (currentAnimation == desiredAnimation)
		{
			return;
		}

		actor = candidate;
		originalAnimation = currentAnimation;
		replacementAnimation = desiredAnimation;
		access.setAnimation(candidate, desiredAnimation);
	}

	void restore()
	{
		T actorToRestore = actor;
		if (actorToRestore == null)
		{
			return;
		}

		int animationToRestore = originalAnimation;
		int ownedReplacementAnimation = replacementAnimation;
		actor = null;
		originalAnimation = 0;
		replacementAnimation = 0;

		if (access.getAnimation(actorToRestore) == ownedReplacementAnimation)
		{
			access.setAnimation(actorToRestore, animationToRestore);
		}
	}
}

package com.injuryanimations;

final class InjuryAnimationPolicy
{
	private static final int NO_ACTION_ANIMATION = -1;

	private InjuryAnimationPolicy()
	{
	}

	static boolean shouldOverride(
		boolean movementEnabled,
		InjuryState injuryState,
		boolean pauseDuringActions,
		int actionAnimation)
	{
		return movementEnabled
			&& injuryState != null
			&& injuryState == InjuryState.INJURED
			&& (!pauseDuringActions || actionAnimation == NO_ACTION_ANIMATION);
	}
}

package com.injuryanimations;

import java.util.Collections;
import java.util.Locale;
import java.util.Set;

final class OffhandAnimationCompatibility
{
	private static final String[] SHIELD_SAFE_NAME_TERMS =
	{
		"shield",
		"ward",
		"lantern",
		"buckler"
	};

	// Add IDs only after the normal injured animation has been observed clipping.
	static final Set<Integer> EXTRA_SHIELD_SAFE_OFFHANDS = Collections.emptySet();

	private OffhandAnimationCompatibility()
	{
	}

	static boolean requiresShieldSafeAnimation(int itemId, String itemName)
	{
		return requiresShieldSafeAnimation(itemId, itemName, EXTRA_SHIELD_SAFE_OFFHANDS);
	}

	static boolean requiresShieldSafeAnimation(
		int itemId,
		String itemName,
		Set<Integer> extraShieldSafeOffhands)
	{
		if (itemId < 0)
		{
			return false;
		}

		if (extraShieldSafeOffhands.contains(itemId))
		{
			return true;
		}

		if (itemName == null)
		{
			return false;
		}

		String normalizedName = itemName.toLowerCase(Locale.ROOT);
		for (String term : SHIELD_SAFE_NAME_TERMS)
		{
			if (normalizedName.contains(term))
			{
				return true;
			}
		}

		return false;
	}
}
